%[text] # Build input signal trace
%[text] Generate data.
signal_design_matrix = [0 100 0; 105 200 40; 205 300 60; 305 400 100; 405 500 50; 510 600 0];

data_table = bevutil1.SignalUtil.getVectorsFromSignalDesignMatrix(signal_design_matrix);

% The "Table data" parameter in Simulink 1D Lookup Table.
t = data_table.X;

% The "Breakpoints 1" parameter in Simulink 1D Lookup Table.
f = data_table.F;

fig = figure; %[output:99120201]
fig.Position(3:4) = [900 300];  % width height %[output:99120201]
bevutil1.SignalUtil.plotLookupTable1D(t, f, InterpolationInterval=0.2, ParentAxes=axes(fig)) %[output:99120201]
